    let ids: Vec<u64> = s.catalog.photos().map(|p| p.id.0).collect();
    s.execute("library.buildPreviews", &json!({"ids": ids, "size": "full"})).unwrap();
    let id = s.activity.list().first().map(|t| t.id).expect("a previews row");
