         "sha256": sha, "sizeBytes": size, "licence": {"name": "Research only", "commercial": "no", "notice": "Not for commercial use."},
         "provenance": "Some dataset", "output": {"kind": "embedding", "dim": 64}, "thresholds": {"matchCosine": 0.42}},
        {"id": "broken", "name": "No hash", "version": "1", "role": "embedder", "url": "https://models.example.org/x.onnx", "output": {"kind": "embedding", "dim": 64}},
    ]});
    std::fs::write(models.join("catalog.json"), catalog.to_string()).unwrap();
    // it is listed like a built-in model, with its own terms, a download address, and the problem with the other entry
    let l = s.execute("faces.models.list", &json!({})).unwrap();
    let m = find(&l, "my-research-model");
    assert_eq!(
        (m["fromCatalog"].clone(), m["downloadHost"].clone(), m["licence"]["commercial"].clone()),
        (json!(true), json!("models.example.org"), json!("no"))
    );
    assert_eq!(m["installed"], false);
    assert_eq!(find(&l, "broken"), &Value::Null);
    assert_eq!(l["catalog"]["models"], 1);
    assert!(l["catalog"]["errors"][0].as_str().unwrap().contains("broken"), "{}", l["catalog"]);
    // nothing is fetched without the terms being accepted
    assert!(s.execute("faces.models.download", &json!({"id": "my-research-model"})).is_err());
    // a file that matches is recognised as that model (not as a draft), so its terms and settings are used
    let seen = s.execute("faces.models.inspect", &json!({"path": file})).unwrap();

    assert_eq!((seen["kind"].clone(), seen["model"]["id"].clone()), (json!("known"), json!("my-research-model")));
    // a finished download of it installs under the catalog's id, with the catalog's licence record
    let staging = models.join(crate::face_download::STAGING);
    std::fs::create_dir_all(&staging).unwrap();
    let staged = staging.join("weights.onnx");
    std::fs::copy(&file, &staged).unwrap();
    s.face_downloads.set_outcome("my-research-model", State::Done { path: staged, sha256: sha });
    let r = s.execute("faces.models.downloads", &json!({})).unwrap();
    assert_eq!(r["downloads"][0]["state"], "installed", "{r}");
    let st = settings_of(&d);
    assert_eq!((st["embedder"].clone(), st["enabled"].clone()), (json!("my-research-model"), json!(true)));
    let l = s.execute("faces.models.list", &json!({})).unwrap();
    assert_eq!(
        (find(&l, "my-research-model")["installed"].clone(), find(&l, "my-research-model")["accepted"]["commercial"].clone()),
        (json!(true), json!("no"))
    );
    // a broken or hostile catalog never stops the list
    for bytes in [&b"{"[..], b"[]", &vec![b'x'; 400_000]] {
        std::fs::write(models.join("catalog.json"), bytes).unwrap();
        let l = s.execute("faces.models.list", &json!({})).unwrap();
        assert!(l["catalog"]["errors"].as_array().is_some_and(|e| !e.is_empty()), "{}", l["catalog"]);
        assert!(find(&l, "sface-2021dec")["id"] == "sface-2021dec");
    }
    let _ = std::fs::remove_dir_all(&d);
}

/// Issue #678: on means something only with a model to run. Turning recognition on with no chosen
/// (installed) recogniser is refused; installing one chooses it and switches recognition on, after
/// which the switch works both ways; removing the last recogniser switches it off again.
#[test]
fn recognition_cannot_be_turned_on_without_a_chosen_model() {
    let d = temp("enable-needs-model");
    let mut s = session(&d);
    for p in [json!({"enabled": true}), json!({})] {
        let e = s.execute("faces.enable", &p).unwrap_err().to_string();
        assert!(e.contains("recognition model"), "{p}: {e}");
    }
    assert_eq!(s.execute("faces.enable", &json!({"enabled": false})).unwrap()["enabled"], false, "off is always allowed");
    assert_eq!(s.execute("faces.models.list", &json!({})).unwrap()["enabled"], false);
    let f = model_file(&d, "m.onnx", 64);
    let r = s.execute("faces.models.install", &json!({"path": f, "acknowledged": true})).unwrap();
    let id = r["installed"]["id"].as_str().unwrap().to_string();
    assert_eq!(r["active"]["enabled"], true, "installing chooses the model and switches recognition on: {r}");
    assert_eq!(s.execute("faces.enable", &json!({"enabled": false})).unwrap()["enabled"], false);
    assert_eq!(s.execute("faces.enable", &json!({"enabled": true})).unwrap()["enabled"], true);
    assert_eq!(s.execute("faces.enable", &json!({})).unwrap()["enabled"], false, "toggles when omitted");
    assert_eq!(s.execute("faces.enable", &json!({})).unwrap()["enabled"], true);
    // the last recogniser goes: nothing is chosen, so recognition is off and stays off
    assert_eq!(s.execute("faces.models.remove", &json!({"id": id})).unwrap()["embedder"], Value::Null);
    let l = s.execute("faces.models.list", &json!({})).unwrap();
    assert_eq!((l["enabled"].clone(), l["embedder"].clone()), (json!(false), Value::Null), "{l}");
    assert!(s.execute("faces.enable", &json!({"enabled": true})).is_err());
    let _ = std::fs::remove_dir_all(&d);
}

//! Forgetting untouched Local browse records: by command and when the library opens; changed,
//! recent and visible records stay; a crash replays it; browsing again brings records back.

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use serde_json::json;

use crate::{LibrarySource, Selection, Session};

fn temp_dir(tag: &str) -> PathBuf {
    let d = std::env::temp_dir().join(format!("lc-forget-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn png(p: &Path, seed: u8) {
    let img = lightcraft_raster::Rgba8::from_fn(16, 12, |x, y| [(x * 9) as u8, (y * 11) as u8, seed, 255]);
    let b =
        crate::export::encode_image(&img, &crate::export::ExportOptions { format: crate::export::ExportFormat::Png, ..Default::default() }).unwrap();
    std::fs::create_dir_all(p.parent().unwrap()).unwrap();
    std::fs::write(p, b).unwrap();
}

fn open(lib: &Path, clock: &Arc<Mutex<String>>) -> Session {
    let mut s = Session::new().with_fs();
    let c = clock.clone();
    s.clock = Box::new(move || c.lock().unwrap().clone());
    s.open_library(lib, false).unwrap();
    s
}

fn set(clock: &Arc<Mutex<String>>, t: &str) {
    *clock.lock().unwrap() = t.to_string();
}

fn local_paths(s: &Session) -> Vec<String> {
    let mut v: Vec<String> = s
        .catalog
        .photos()
        .filter(|p| p.local)
        .filter_map(|p| match &p.source {
            lightcraft_catalog::Source::File { path } => Path::new(path).file_name().map(|n| n.to_string_lossy().to_string()),
            _ => None,
        })
        .collect();
    v.sort();
    v
}

/// Leave the folder view (nothing browsed is visible or selected any more).
fn look_elsewhere(s: &mut Session) {
    s.execute("library.source", &json!({"kind": "all"})).unwrap();
    s.selection = Selection::default();
    s.previous_active = None;
    s.undo.clear();
}

#[test]
fn untouched_records_of_unbrowsed_folders_are_forgotten_and_come_back() {
    let root = temp_dir("cmd");
    let (a, b, lib) = (root.join("a"), root.join("b"), root.join("lib"));
    for (i, n) in ["a1.png", "a2.png", "a3.png"].iter().enumerate() {
        png(&a.join(n), i as u8);
    }
    png(&b.join("b1.png"), 7);
    let clock = Arc::new(Mutex::new("2026-08-01T10:00:00".to_string()));
    let mut s = open(&lib, &clock);
    s.execute("library.browse", &json!({"path": a.to_string_lossy()})).unwrap();
    // the user rates a2 (a change: kept)
    let a2 = s.catalog.photos().find(|p| p.file_name == "a2.png").unwrap().id;
    s.selection = Selection::single(a2);
    s.execute("photo.rate", &json!({"rating": 3})).unwrap();
    set(&clock, "2026-08-25T10:00:00");
    s.execute("library.browse", &json!({"path": b.to_string_lossy()})).unwrap();
    look_elsewhere(&mut s);

    // 40 days after a was browsed, 16 after b
    set(&clock, "2026-09-10T10:00:00");
    let dry = s.execute("library.forgetLocal", &json!({"dryRun": true})).unwrap();
    assert_eq!(
        (dry["local"].as_u64(), dry["forgotten"].as_u64(), dry["keptTouched"].as_u64(), dry["keptRecent"].as_u64()),
        (Some(4), Some(2), Some(1), Some(1)),
        "{dry}"
    );
    assert_eq!(local_paths(&s).len(), 4, "a dry run changes nothing");
    let r = s.execute("library.forgetLocal", &json!({})).unwrap();
    assert_eq!(r["forgotten"], 2, "{r}");
    assert_eq!(local_paths(&s), vec!["a2.png", "b1.png"]);
    // files on disk are untouched
    assert!(["a1.png", "a2.png", "a3.png"].iter().all(|n| a.join(n).exists()));
    // not an undo step
    assert!(s.undo.is_empty());

    // a crash now: the log replays the same catalog
    let expect = s.catalog.to_snapshot();
    drop(s);
    let mut s = open(&lib, &clock);
    assert_eq!(s.library.as_ref().unwrap().report.failed, 0);
    assert_eq!(s.catalog.to_snapshot(), expect, "nothing more to forget on open, same state after replay");

    // browsing a again brings the forgotten files back, fresh; the rated one is the same record
    let r = s.execute("library.browse", &json!({"path": a.to_string_lossy()})).unwrap();
    assert_eq!((r["photos"].as_u64(), r["new"].as_u64()), (Some(3), Some(2)), "{r}");
    assert_eq!(s.catalog.photo(a2).unwrap().rating, 3);
    // while a is shown, nothing in it goes, whatever the time
    set(&clock, "2027-09-10T10:00:00");
    assert_eq!(s.execute("library.forgetLocal", &json!({"dryRun": true})).unwrap()["forgotten"], 1, "only b1 (not visible)");
    let _ = std::fs::remove_dir_all(&root);
}

#[test]
fn opening_the_library_forgets_per_the_preference() {
    let root = temp_dir("open");
    let (a, lib) = (root.join("a"), root.join("lib"));
    png(&a.join("x.png"), 1);
    png(&a.join("y.png"), 2);
    let clock = Arc::new(Mutex::new("2026-08-01T10:00:00".to_string()));
    let mut s = open(&lib, &clock);
    s.execute("library.browse", &json!({"path": a.to_string_lossy()})).unwrap();
    look_elsewhere(&mut s);
    // 0 = never
    let r = s.execute("library.preferences", &json!({"forgetLocalDays": 0})).unwrap();
    assert_eq!(r["forgetLocalDays"], 0);
    s.close_library().unwrap();
    drop(s);
    set(&clock, "2027-01-01T10:00:00");
    let mut s = open(&lib, &clock);
    assert_eq!(local_paths(&s).len(), 2, "never");
    assert!(s.library.as_ref().unwrap().forgot_local.is_none());
    // back to 30 days: the next open forgets them
    s.execute("library.preferences", &json!({"forgetLocalDays": 30})).unwrap();
    s.source = LibrarySource::All;
    s.close_library().unwrap();
    drop(s);
    let s = open(&lib, &clock);
    assert!(local_paths(&s).is_empty());
    let info = {
        let mut s = s;
        s.execute("library.info", &json!({})).unwrap()
    };
    assert_eq!(info["forgotLocal"]["forgotten"], 2, "{info}");
    assert!(a.join("x.png").exists() && a.join("y.png").exists());
    let _ = std::fs::remove_dir_all(&root);
}

/// A file with an XMP sidecar comes in with the sidecar's rating and keywords: that is its
/// browse state, not a user change, so the record is forgotten like any other — and the sidecar
/// stays byte for byte, so browsing again reads the same values back.
#[test]
fn sidecar_values_are_not_user_changes_and_sidecars_stay() {
    let root = temp_dir("xmp");
    let (a, lib) = (root.join("a"), root.join("lib"));
    png(&a.join("x.png"), 1);
    let x = a.join("x.png").to_string_lossy().to_string();
    let mut p = lightcraft_catalog::Photo::new(
        lightcraft_catalog::PhotoId(1),
        lightcraft_catalog::Source::File { path: x.clone() },
        "x.png",
        "PNG",
        16,
        12,
        "2026-01-01T00:00:00",
    );
    p.rating = 4;
    p.meta.keywords = vec!["dunes".into()];
    let side = crate::sidecar::sidecar_path(&x, Default::default());
    std::fs::write(&side, crate::sidecar::sidecar_packet(&p, &lightcraft_catalog::Catalog::new())).unwrap();
    let packet = std::fs::read(&side).unwrap();

    let clock = Arc::new(Mutex::new("2026-08-01T10:00:00".to_string()));
    let mut s = open(&lib, &clock);
    s.execute("library.browse", &json!({"path": a.to_string_lossy()})).unwrap();
    let rec = s.catalog.photos().find(|p| p.local).unwrap().clone();
    assert_eq!((rec.rating, rec.meta.keywords.clone()), (4, vec!["dunes".to_string()]), "read from the sidecar");
    look_elsewhere(&mut s);
    set(&clock, "2026-10-01T10:00:00");
    assert_eq!(s.execute("library.forgetLocal", &json!({})).unwrap()["forgotten"], 1);
    assert_eq!(std::fs::read(&side).unwrap(), packet, "the sidecar is untouched");
    s.execute("library.browse", &json!({"path": a.to_string_lossy()})).unwrap();
    let back = s.catalog.photos().find(|p| p.local).unwrap();
    assert_ne!(back.id, rec.id, "a fresh record");
    assert_eq!((back.rating, back.meta.keywords.clone()), (4, vec!["dunes".to_string()]));
    let _ = std::fs::remove_dir_all(&root);
}

/// A catalog written before browse times existed: its Local records are kept on the first open
/// (their folders are stamped then), and forgotten only once the period has passed since.
#[test]
fn upgraded_catalogs_forget_nothing_at_first() {
    let root = temp_dir("upgrade");
    let (a, lib) = (root.join("a"), root.join("lib"));
    png(&a.join("x.png"), 1);
    let clock = Arc::new(Mutex::new("2026-08-01T10:00:00".to_string()));
    let mut s = open(&lib, &clock);
    s.execute("library.browse", &json!({"path": a.to_string_lossy()})).unwrap();
    look_elsewhere(&mut s);
    s.close_library().unwrap();
    drop(s);
    // strip the times and baselines, as an older version would have written the snapshot
    let snap = std::fs::read_to_string(lib.join("catalog.snap")).unwrap();
    let mut v: serde_json::Value = serde_json::from_str(&snap).unwrap();
    v["catalog"].as_object_mut().unwrap().remove("browsed");
    for p in v["catalog"]["photos"].as_object_mut().unwrap().values_mut() {
        p.as_object_mut().unwrap().remove("local_baseline");
    }
    std::fs::write(lib.join("catalog.snap"), serde_json::to_vec(&v).unwrap()).unwrap();
    set(&clock, "2027-01-01T10:00:00");
    let s = open(&lib, &clock);
    assert_eq!(local_paths(&s).len(), 1, "kept on the first open after the upgrade");
    assert_eq!(s.catalog.last_browsed(&a.to_string_lossy()), Some("2027-01-01T10:00:00"));
    drop(s);
    set(&clock, "2027-02-15T10:00:00");
    let s = open(&lib, &clock);
    assert!(local_paths(&s).is_empty(), "the untouched legacy record goes once 30 days passed");
    let _ = std::fs::remove_dir_all(&root);
}

//! Import: recursive folders, duplicate detection by content, add vs copy into the library.

use std::path::Path;

use serde_json::{Value, json};

use crate::Session;

fn temp_dir(tag: &str) -> std::path::PathBuf {
    let d = std::env::temp_dir().join(format!("lc-import-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(&d).unwrap();
    d
}

/// A small procedural PNG (distinct per seed).
fn write_png(path: &Path, seed: u8) {
    let (w, h) = (48usize, 32usize);
    let data: Vec<[u8; 4]> = (0..w * h).map(|i| [(i % w * 5) as u8, (i / w * 7) as u8, seed, 255]).collect();
    let img = lightcraft_raster::Rgba8 { width: w, height: h, data };
    let bytes = lightcraft_codecs::encode_png(&lightcraft_codecs::EncodeImage::rgba8(&img), &lightcraft_codecs::EncodeMeta::default()).unwrap();
    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
    std::fs::write(path, bytes).unwrap();
    // undated files take the file's date: the tests' clock time (2026-01-14T05:58:48)
    let t = std::time::UNIX_EPOCH + std::time::Duration::from_secs(1_768_370_328);
    std::fs::File::options().write(true).open(path).unwrap().set_modified(t).unwrap();
}

fn ids(v: &Value, key: &str) -> usize {
    v[key].as_array().map(Vec::len).unwrap_or(0)
}

#[test]
fn recursive_import_with_duplicates() {
    let src = temp_dir("src");
    write_png(&src.join("a.png"), 1);
    write_png(&src.join("trip/b.png"), 2);
    write_png(&src.join("trip/day2/c.PNG"), 3);
    std::fs::copy(src.join("a.png"), src.join("trip/a-copy.png")).unwrap(); // same bytes
    write_png(&src.join(".hidden/x.png"), 9);
    std::fs::write(src.join("notes.txt"), "not a photo").unwrap();
    std::fs::write(src.join("trip/broken.jpg"), "garbage").unwrap();

    let mut s = Session::new().with_fs();
    let r = s.execute("library.import", &json!({"paths": [src.to_string_lossy()]})).unwrap();
    assert_eq!(r["scanned"], 5, "{r}"); // a, b, c, a-copy, broken (hidden + txt skipped)
    assert_eq!(ids(&r, "imported"), 3, "{r}");
    assert_eq!(ids(&r, "duplicates"), 1, "{r}");
    assert_eq!(r["duplicates"][0]["reason"], "content");
    assert_eq!(ids(&r, "failed"), 1, "{r}");
    assert_eq!(s.catalog.len(), 3);
    assert!(s.catalog.photos().all(|p| p.content_hash.as_ref().is_some_and(|h| h.len() == 32) && p.width == 48));

    // importing again: everything is a duplicate (by path), one undo step for the first import
    let r2 = s.execute("library.import", &json!({"paths": [src.to_string_lossy()]})).unwrap();
    assert_eq!(ids(&r2, "imported"), 0);
    assert_eq!(r2["duplicates"].as_array().unwrap().iter().filter(|d| d["reason"] == "path").count(), 3);
    s.execute("edit.undo", &json!({})).unwrap();
    assert_eq!(s.catalog.len(), 0);
    let _ = std::fs::remove_dir_all(&src);
}

#[test]
fn copy_into_library_and_persist() {
    let src = temp_dir("copysrc");
    let lib = temp_dir("copylib");
    write_png(&src.join("one.png"), 4);
    write_png(&src.join("sub/one.png"), 5); // same name, different content
    let mut s = Session::new().with_fs();
    assert!(s.execute("library.import", &json!({"paths": [src.to_string_lossy()], "mode": "copy"})).is_err(), "copy needs a library");
    s.open_library(&lib, false).unwrap();
    let r = s.execute("library.import", &json!({"paths": [src.to_string_lossy()], "mode": "copy"})).unwrap();
    assert_eq!(ids(&r, "imported"), 2, "{r}");
    let paths: Vec<String> = s
        .catalog
        .photos()
        .map(|p| match &p.source {
            lightcraft_catalog::Source::File { path } => path.clone(),
            _ => panic!(),
        })
        .collect();
    for p in &paths {
        assert!(Path::new(p).starts_with(lib.join("Originals")), "{p}");
        assert!(Path::new(p).exists());
    }
    assert_ne!(paths[0], paths[1], "unique names");
    // originals deleted from the source: the library copies remain usable after a restart
    std::fs::remove_dir_all(&src).unwrap();
    drop(s);
    let mut s = Session::new().with_fs();
    s.open_library(&lib, false).unwrap();
    assert_eq!(s.catalog.len(), 2);
    let id = s.catalog.photos().next().unwrap().id;
    assert!(s.render_now(id, 32, 32).is_ok());
    // the library folder itself is never re-imported
    let r = s.execute("library.import", &json!({"paths": [lib.to_string_lossy()]})).unwrap();
    assert_eq!(r["scanned"], 0, "{r}");
    let _ = std::fs::remove_dir_all(&lib);
}

