    xmlns:crs="http://ns.adobe.com/camera-raw-settings/1.0/"
    xmlns:other="http://example.com/other/1.0/"
    xmp:Rating="2"
    crs:Version="99.0"
    crs:Exposure2012="+0.65"
    crs:HasSettings="True"
    other:Secret="keep me">
